function handbook(){const u=state.handbookUI,query=u.query.trim().toLowerCase(),rows=state.records.filter(r=>(!state.filter||state.filter==='all'||r.kind===state.filter)&&(!query||r.text.toLowerCase().includes(query))&&(u.scope==='all'||(u.scope==='today'?r.savedDay===state.day:r.contentDay===u.scope))).sort((a,b)=>b.savedDay.localeCompare(a.savedDay));const pages=Math.max(1,Math.ceil(rows.length/5));u.page=Math.min(u.page,pages-1);return heading('手账','搜索自己的原文，事件与日记分别保留。')+`<div class="subnav">${[['all','全部'],['event','事件'],['diary','日记']].map(([k,n])=>`<button class="btn ${(!state.filter&&k==='all')||state.filter===k?'soft':''}" data-full="record-filter" data-id="${k}">${n}</button>`).join('')}<a href="#diary">写日记 →</a></div><section class="card"><div class="form-grid"><label class="field">搜索原文<input id="handbook-search" value="${esc(u.query)}" placeholder="一句话、一件事…"></label><label class="field">日期范围<select id="handbook-scope"><option value="all" ${u.scope==='all'?'selected':''}>所有日期</option><option value="today" ${u.scope==='today'?'selected':''}>实际保存于今天</option>${!['all','today'].includes(u.scope)?`<option value="${u.scope}" selected>内容所属 ${u.scope}</option>`:''}</select></label></div><button class="btn" data-full="search-records">搜索</button><div class="mt">${rows.slice(u.page*5,u.page*5+5).map(recordRow).join('')||'<p class="empty">没有找到匹配原文，换个词试试。</p>'}</div><div class="row between wrap mt"><button class="btn compact" data-full="record-page" data-id="-1" ${u.page<=0?'disabled':''}>上一页</button><span class="small muted">${rows.length} 条 · ${u.page+1} / ${pages}</span><button class="btn compact" data-full="record-page" data-id="1" ${u.page+1>=pages?'disabled':''}>下一页</button></div></section>`}
function recordPage(){const r=state.records.find(x=>x.id===state.activeRecord);if(!r)return back('handbook')+heading('还没有选择事件','从手账打开一条记录。');const statuses={queued:'分析中',failed:'分析失败',needsInput:'待补充',ready:'建议待确认',idle:'尚未分析'};return back(r.planId?'plans':'handbook')+heading('这一件事','原文、补充与确认依据，一起保留。')+`<section class="card mb"><div class="row between wrap"><span class="tag ${r.revoked?'orange':'green'}">${r.revoked?'已撤销':'原文已保存'}</span><span class="small muted">内容 ${r.contentDay} · 保存 ${r.savedDay} · 原文 v${r.version}</span></div><p class="detail-original mt">${esc(r.text)}</p>${r.supplement?`<p class="quote">你的补充：${esc(r.supplement)}</p>`:''}<div class="row wrap mt"><button class="btn compact" data-full="edit-event">编辑原文</button><button class="text-button" data-full="link-fact">关联同一件事</button><button class="text-button" data-full="record-audit">查看审计</button>${!r.revoked?'<button class="btn compact danger" data-full="revoke-event">撤销记录</button>':''}</div>${r.sameFactAs?'<p class="note mt">由你主动确认同一事实，两份原文保留，共享入账结果。</p>':''}</section><section class="card"><div class="section-title"><h2>分析与奖励建议</h2><span class="tag blue">${r.revoked?'不再参与新分析':r.settled?'已确认入账':statuses[r.analysisStatus]||'脚本预览'}</span></div>${r.revoked?'<p class="muted">原文与历史审计仍保留，属性不再累计；已发金币保留。</p>':r.settled?`<div class="reward-strip">${r.reused?'共享已有事实入账':r.award===undefined?'历史样例已结算':`已入账 ${r.award} 币 · ${esc(r.attribute||'属性依据当时建议')}`}</div><details><summary>查看确认时依据</summary><div class="body">${esc(r.confirmedSnapshot?.text||r.text)}<br>${esc(r.confirmedSnapshot?.attribute||r.attribute||'历史样例无新增属性')}<br>后续编辑不覆盖已经确认的依据，也不自动再次发奖。</div></details>`:r.analysisStatus==='queued'?'<p class="quote">正在生成分析示例，原文已经保存。</p><button class="btn" data-full="cancel-analysis">取消分析</button>':r.analysisStatus==='failed'?'<p class="quote">本次模拟调用失败，原文和补充仍在。</p><button class="btn primary" data-full="analyze">重试分析</button>':r.suggestion?rewardView(r):`<p class="muted small">${r.analysisIntent==='never'?'这条记录选择了只记录；你仍可主动发起分析。':'根据当前事件建议属性、金币和目标关联，不要求自己判成果档位。'}</p>${r.clarify?`<p class="quote">${esc(r.clarify)}</p><button class="btn primary" data-action="correct-record">补充这件事</button>`:'<button class="btn primary mt" data-full="analyze">现在分析（模拟）</button>'}`}${!r.settled&&!r.revoked?'<details><summary>分析状态演示</summary><label class="field">这次模拟结果<select id="analysis-demo-result"><option value="ready">正常生成建议</option><option value="needsInput">事实不足，需要补充</option><option value="failed">调用失败，保留输入</option></select></label></details>':''}<p class="daily-note">${esc(modelCaption())} · 所有分析为本机脚本示例</p></section>`}
function pending(){const records=state.records.filter(r=>r.kind==='event'&&!r.settled&&!r.revoked);return heading('待处理','原文已经保存，按自己的时间慢慢处理。')+`<section class="card">${records.map(r=>`<div class="list-row"><div><h3>${esc(r.text.slice(0,45))}</h3><small>${r.savedDay} · ${r.suggestion?'建议待确认':r.clarify?'待补充':r.analysisStatus==='failed'?'分析失败':'待分析'}</small></div><button class="btn compact" data-action="open-record" data-id="${r.id}">继续</button></div>`).join('')||'<p class="empty">目前没有待处理的事件。</p>'}</section>`}
function beginAnalysis(r){if(!r||r.settled||r.revoked)return;if(state.model.source==='off'){openDialog('AI 当前已关闭','<p>原文保留。启用个人模型后再分析，也可以一直只记录。</p>',()=>{closeDialog();go('models')},'查看模型设置');return}const mode=!['demo-chat-model','example-chat'].includes(state.model.model)?'failed':$('#analysis-demo-result')?.value||'ready',token=uid();r.analysisStatus='queued';r.analysisToken=token;save();render();setTimeout(()=>{if(r.analysisToken!==token||r.revoked)return;if(mode==='failed'){r.analysisStatus='failed';delete r.suggestion}else if(mode==='needsInput'){delete r.suggestion;r.clarify='关于这件事，你实际做了什么，或有什么具体进展？';r.analysisStatus='needsInput'}else{suggestRecord(r);r.analysisStatus=r.suggestion?'ready':'needsInput'}save();if(state.route==='record'&&state.activeRecord===r.id)render()},650)}
function contextForDiary(r){return [r.text,...state.records.filter(x=>x.id!==r.id&&x.contentDay===r.contentDay&&!x.revoked).map(x=>x.text),...state.plans.map(p=>state.outcomes[p.id+'@'+r.contentDay]?.status==='done'?p.title:'').filter(Boolean),...Object.entries(state.care).filter(([k])=>k.startsWith(r.contentDay+'@')).map(([k,v])=>k.split('@')[1]+'：'+v),...r.sessions.flatMap(s=>s.turns.map(t=>t.answer||''))].join(' ')}
function reviewCandidates(r){const context=contextForDiary(r),used=new Set(r.sessions.flatMap(s=>s.turns.map(t=>t.topic)));const questions=[];if(/沮丧|着急|难过|烦|疲惫|不开心|挫折/.test(context)&&!/开心|支持|轻松|感谢|朋友帮助/.test(context)&&!used.has('support'))questions.push({topic:'support',text:'除了已经记下的困难，今天有没有一个让你稍微轻松，或感觉被支持的片段？没有也没关系。'});if(!/睡眠|睡了|起床|几点睡/.test(context)&&!used.has('sleep'))questions.push({topic:'sleep',text:'回看这一天，睡眠和精神状态有什么想补充的吗？可以跳过。'});if(!/饮食|吃饭|三餐|早餐|午餐|晚餐/.test(context)&&!used.has('food'))questions.push({topic:'food',text:'今天吃饭和照顾自己这方面，有没有想留下一句的？'});if(!/运动|散步|跑步|训练|活动|健身/.test(context)&&!used.has('movement'))questions.push({topic:'movement',text:'今天有没有让身体活动或休息的一小段时间，想留作回顾？'});return questions}
function diarySessionHTML(r,s){return `<details class="review-session" open><summary>辅助回顾 · ${s.day} · ${s.state==='finished'?'已结束':'可继续'}</summary>${s.turns.map((t,i)=>`<div class="quote"><strong>AI 引导 ${i+1}</strong><p>${esc(t.question)}</p></div>${t.state==='asked'?`<label class="field">我的回答<textarea id="review-answer" data-review-turn="${t.id}" placeholder="想说多少都可以，也可以跳过。">${esc(state.drafts['review-turn@'+t.id]||'')}</textarea></label><div class="row wrap"><button class="btn primary" data-full="answer-review" data-id="${s.id}">保存回答，继续</button><button class="btn" data-full="skip-review" data-id="${s.id}">跳过</button><button class="text-button" data-full="finish-review" data-id="${s.id}">结束问答</button></div>`:`<div class="review-answer"><strong>我的回答</strong><p>${t.state==='skipped'?'已跳过':esc(t.answer)}</p></div>`}`).join('')}${s.analysis?`<div class="note mt"><strong>AI 辅助分析 · 示例</strong><p>${esc(s.analysis)}</p></div>`:''}<details><summary>查看当时参考的日记与事件</summary><p class="small muted">日记原文 v${s.snapshot.version} · 来源 ${s.snapshot.sources.length} 条</p><p class="detail-original">${esc(s.snapshot.text)}</p>${s.snapshot.sources.map(x=>`<p class="small muted">${esc(x.text)}</p>`).join('')}</details></details>`}
function diaryPage(){const r=state.diaryId?state.records.find(x=>x.id===state.diaryId):diaryRecord(),draftKey=r?'diary-record@'+r.id:'diary@'+state.day,active=r?.sessions.find(s=>s.state==='active');return back('handbook')+heading('晚间日记','我的原文、AI 的引导、我的回答和辅助分析，分别保留。')+`<div class="two-col"><div class="stack"><section class="card"><div class="section-title"><h2>我写下的日记</h2><span class="tag ${r?'green':''}">${r?'已保存 · v'+r.version:'本机草稿'}</span></div><textarea id="diary-text" data-draft="${draftKey}" style="min-height:210px">${esc(state.drafts[draftKey]??r?.text??'')}</textarea><div class="row between wrap mt"><span class="small muted">${r?'首次保存日 '+r.savedDay:'保存后计入日记记录日'}</span><button class="btn primary" data-full="save-diary">保存日记</button></div></section><section class="card"><div class="section-title"><h2>AI 辅助回顾</h2><span class="tag blue">与原文分开</span></div><p class="small muted">优先避开已在日记、事件、计划和之前问答中覆盖的内容。所有问题和回答保留，原文不被自动改写。</p>${r?.sessions.length?r.sessions.map(s=>diarySessionHTML(r,s)).join(''):''}${!active?`<button class="btn soft mt" data-full="start-review" ${!r?'disabled':''}>${r?.sessions.length?'再回顾一下':'帮我回顾一下'}</button>`:''}${!r?'<p class="daily-note">先保存日记，再开始辅助回顾。</p>':''}</section></div><aside class="card"><h3>当天已经记录的</h3>${state.records.filter(x=>x.id!==r?.id&&x.contentDay===(r?.contentDay||state.day)&&!x.revoked).map(x=>`<p class="quote">${esc(x.text)}</p>`).join('')||'<p class="empty">当天事件会出现在这里，无需抄进日记。</p>'}<a href="#today" class="text-button">返回今天，记一件事 →</a></aside></div>`}
function startReview(){const r=state.records.find(x=>x.id===state.diaryId)||diaryRecord();if(!r)return;if(reviewModel().source==='off'||!['demo-chat-model','example-chat'].includes(reviewModel().model))return toast('辅助模型当前不可用；日记原文已保存，可先到模型设置核对。');const existing=r.sessions.find(s=>s.state==='active');if(existing)return render();const candidates=reviewCandidates(r);if(!candidates.length)return toast('已记录的内容比较完整，这次没有新的示例问题。');const q=candidates[0];r.sessions.push({id:uid(),day:state.day,state:'active',turns:[{id:uid(),topic:q.topic,question:q.text,answer:'',state:'asked'}],snapshot:{text:r.text,version:r.version,sources:state.records.filter(x=>x.id!==r.id&&x.contentDay===r.contentDay&&!x.revoked).map(x=>({id:x.id,text:x.text,version:x.version}))}});state.diaryId=r.id;save();render()}
function finishReview(r,s){s.state='finished';s.analysis='这份回顾结合你当时的原文与回答，保留了当天的行动和感受。可以从一个自己愿意继续的小安排开始，不要求把每一天过得完美。';s.endedAt=new Date().toISOString();save();render()}
function saveFullDiary(){const text=$('#diary-text').value.trim();if(!text)return toast('先写一点想留下的内容。');let r=state.diaryId?state.records.find(x=>x.id===state.diaryId):diaryRecord();if(r){if(r.text!==text){(r.revisions ||= []).push({version:r.version,text:r.text});r.text=text;r.version++}}else{r=addRecord(text,'diary');r.version=1;r.sessions=[]}state.diaryId=r.id;delete state.drafts['diary@'+state.day];delete state.drafts['diary-record@'+r.id];save();render();toast('日记原文已保存，辅助问答保持独立。')}
function feedback(){return back('my')+heading('意见与问题','提交建议，查看进度和站内回复。')+`<section class="card"><span class="tag green">仅你与授权管理员可见</span><label class="field">标题<input id="feedback-title" maxlength="100"></label><label class="field">具体内容<textarea id="feedback-text" maxlength="3000"></textarea></label><button class="btn primary" data-action="submit-feedback">提交反馈</button></section><section class="card mt"><h2>我的反馈</h2>${state.feedback.filter(f=>!f.username||f.username===state.account.username).map(f=>`<article class="mt"><h3>${esc(f.title)}</h3><span class="tag">${f.reply?'已回复':'待处理'}</span><p class="feedback-message">${esc(f.text)}</p>${f.reply?`<p class="feedback-message reply"><strong>管理员回复</strong><br>${esc(f.reply)}</p>`:''}</article>`).join('')||'<p class="empty">提交后可在这里查看。</p>'}</section>`}
